  1→import { db } from "@orksys-survey/db";
  2→import { survey } from "@orksys-survey/db/schema/survey";
  3→import { and, count, desc, eq, ilike, inArray, or } from "drizzle-orm";
  4→import { z } from "zod";
  5→
  6→import {
  7→	adminProcedure,
  8→	organizationProcedure,
  9→	ownerProcedure,
 10→	publicProcedure,
 11→} from "../index";
 12→
 13→// Input schemas
 14→const surveyCreateSchema = z.object({
 15→	slug: z
 16→		.string()
 17→		.min(1)
 18→		.max(100)
 19→		.regex(/^[a-z0-9-]+$/),
 20→	title: z.string().min(1).max(255),
 21→	description: z.string().max(2000).optional(),
 22→	settings: z
 23→		.object({
 24→			showProgressBar: z.boolean().optional(),
 25→			showQuestionNumbers: z.boolean().optional(),
 26→			shuffleQuestions: z.boolean().optional(),
 27→			allowMultipleResponses: z.boolean().optional(),
 28→			requireAuth: z.boolean().optional(),
 29→			collectMetadata: z.boolean().optional(),
 30→			thankYouMessage: z.string().optional(),
 31→			redirectUrl: z.string().url().optional(),
 32→			displayMode: z.enum(["one_at_a_time", "list"]).optional(),
 33→			theme: z
 34→				.object({
 35→					primaryColor: z.string().optional(),
 36→					backgroundColor: z.string().optional(),
 37→					fontFamily: z.string().optional(),
 38→				})
 39→				.optional(),
 40→		})
 41→		.optional(),
 42→});
 43→
 44→const surveyUpdateSchema = surveyCreateSchema.partial();
 45→
 46→const surveyListSchema = z.object({
 47→	page: z.number().int().min(1).default(1),
 48→	limit: z.number().int().min(1).max(100).default(20),
 49→	status: z.enum(["draft", "published", "closed", "archived"]).optional(),
 50→	search: z.string().optional(),
 51→});
 52→
 53→const surveyChangeStatusSchema = z.object({
 54→	id: z.string(),
 55→	status: z.enum(["draft", "published", "closed", "archived"]),
 56→});
 57→
 58→// Generate unique ID
 59→function generateId(): string {
 60→	return `survey_${Date.now()}_${Math.random().toString(36).substring(2, 11)}`;
 61→}
 62→
 63→export const surveyRouter = {
 64→	// List surveys for the organization
 65→	list: organizationProcedure
 66→		.input(surveyListSchema)
 67→		.handler(async ({ input, context }) => {
 68→			const { page, limit, status, search } = input;
 69→			const offset = (page - 1) * limit;
 70→
 71→			const conditions = [
 72→				eq(survey.organizationId, context.activeOrganization.id),
 73→			];
 74→
 75→			if (status) {
 76→				conditions.push(eq(survey.status, status));
 77→			}
 78→
 79→			if (search) {
 80→				const searchCondition = or(
 81→					ilike(survey.title, `%${search}%`),
 82→					ilike(survey.description, `%${search}%`),
 83→				);
 84→				if (searchCondition) {
 85→					conditions.push(searchCondition);
 86→				}
 87→			}
 88→
 89→			const [surveys, totalResult] = await Promise.all([
 90→				db
 91→					.select()
 92→					.from(survey)
 93→					.where(and(...conditions))
 94→					.orderBy(desc(survey.createdAt))
 95→					.limit(limit)
 96→					.offset(offset),
 97→				db
 98→					.select({ count: count() })
 99→					.from(survey)
100→					.where(and(...conditions)),
101→			]);
102→
103→			return {
104→				data: surveys,
105→				pagination: {
106→					page,
107→					limit,
108→					total: totalResult[0]?.count ?? 0,
109→					totalPages: Math.ceil((totalResult[0]?.count ?? 0) / limit),
110→				},
111→			};
112→		}),
113→
114→	// Get survey by ID (organization members)
115→	getById: organizationProcedure
116→		.input(z.object({ id: z.string() }))
117→		.handler(async ({ input, context }) => {
118→			const result = await db
119→				.select()
120→				.from(survey)
121→				.where(
122→					and(
123→						eq(survey.id, input.id),
124→						eq(survey.organizationId, context.activeOrganization.id),
125→					),
126→				)
127→				.limit(1);
128→
129→			if (!result[0]) {
130→				throw new Error("Survey not found");
131→			}
132→
133→			return result[0];
134→		}),
135→
136→	// Get published survey by slug (public - for survey runner)
137→	getBySlug: publicProcedure
138→		.input(z.object({ slug: z.string() }))
139→		.handler(async ({ input }) => {
140→			const result = await db
141→				.select()
142→				.from(survey)
143→				.where(and(eq(survey.slug, input.slug), eq(survey.status, "published")))
144→				.limit(1);
145→
146→			if (!result[0]) {
147→				throw new Error("Survey not found");
148→			}
149→
150→			return result[0];
151→		}),
152→
153→	// Create new survey
154→	create: adminProcedure
155→		.input(surveyCreateSchema)
156→		.handler(async ({ input, context }) => {
157→			// Check for duplicate slug
158→			const existing = await db
159→				.select()
160→				.from(survey)
161→				.where(eq(survey.slug, input.slug))
162→				.limit(1);
163→
164→			if (existing[0]) {
165→				throw new Error("A survey with this slug already exists");
166→			}
167→
168→			const id = generateId();
169→			await db.insert(survey).values({
170→				id,
171→				slug: input.slug,
172→				title: input.title,
173→				description: input.description ?? null,
174→				status: "draft",
175→				settings: input.settings ?? null,
176→				userId: context.session.user.id,
177→				organizationId: context.activeOrganization.id,
178→			});
179→
180→			const result = await db
181→				.select()
182→				.from(survey)
183→				.where(eq(survey.id, id))
184→				.limit(1);
185→			return result[0];
186→		}),
187→
188→	// Update survey
189→	update: adminProcedure
190→		.input(z.object({ id: z.string(), data: surveyUpdateSchema }))
191→		.handler(async ({ input, context }) => {
192→			// Verify ownership
193→			const existing = await db
194→				.select()
195→				.from(survey)
196→				.where(
197→					and(
198→						eq(survey.id, input.id),
199→						eq(survey.organizationId, context.activeOrganization.id),
200→					),
201→				)
202→				.limit(1);
203→
204→			if (!existing[0]) {
205→				throw new Error("Survey not found");
206→			}
