 91→			}
 92→
 93→			// Get questions and logic rules for the survey in parallel
 94→			const [questions, logicRules] = await Promise.all([
 95→				db
 96→					.select()
 97→					.from(question)
 98→					.where(eq(question.surveyId, surveyResult[0].id))
 99→					.orderBy(question.order),
100→				db
101→					.select()
102→					.from(logicRule)
103→					.where(eq(logicRule.surveyId, surveyResult[0].id)),
104→			]);
105→
106→			return {
107→				survey: surveyResult[0],
108→				questions,
109→				logicRules,
110→			};
111→		}),
112→
113→	// PUBLIC - Submit response
114→	submit: publicProcedure
115→		.input(submitResponseSchema)
116→		.handler(async ({ input }) => {
117→			// Verify survey exists and is published
118→			const surveyResult = await db
119→				.select()
120→				.from(survey)
121→				.where(
122→					and(eq(survey.id, input.surveyId), eq(survey.status, "published")),
123→				)
124→				.limit(1);
125→
126→			if (!surveyResult[0]) {
127→				throw new Error("Survey not found or not published");
128→			}
129→
130→			// Check for duplicate fingerprint if provided and multiple responses NOT allowed
131→			if (
132→				input.fingerprint &&
133→				!surveyResult[0].settings?.allowMultipleResponses
134→			) {
135→				const existingResponse = await db
136→					.select()
137→					.from(response)
138→					.where(
139→						and(
140→							eq(response.surveyId, input.surveyId),
141→							eq(response.fingerprint, input.fingerprint),
142→						),
143→					)
144→					.limit(1);
145→
146→				if (existingResponse[0]) {
147→					throw new Error("You have already responded to this survey");
148→				}
149→			}
150→
151→			// Verify all questions belong to this survey
152→			const questionIds = input.answers.map((a) => a.questionId);
153→			if (questionIds.length > 0) {
154→				const questions = await db
155→					.select()
156→					.from(question)
157→					.where(inArray(question.id, questionIds));
158→
159→				for (const q of questions) {
160→					if (q.surveyId !== input.surveyId) {
161→						throw new Error(`Question ${q.id} does not belong to this survey`);
162→					}
163→				}
164→			}
165→
166→			// Create response and answers in a transaction
167→			const responseId = generateResponseId();
168→			const now = new Date();
169→
170→			await db.insert(response).values({
171→				id: responseId,
172→				surveyId: input.surveyId,
173→				respondentId: input.respondentId ?? null,
174→				fingerprint: input.fingerprint ?? null,
175→				metadata: input.metadata ?? null,
176→				isComplete: input.isComplete,
177→				startedAt: now,
178→				completedAt: input.isComplete ? now : null,
179→			});
180→
181→			// Insert answers
182→			if (input.answers.length > 0) {
183→				const answersToInsert = input.answers.map((a) => ({
184→					id: generateAnswerId(),
185→					responseId,
186→					questionId: a.questionId,
187→					value: a.value,
188→				}));
189→
190→				await db.insert(answer).values(answersToInsert);
191→			}
192→
193→			return { success: true, responseId };
194→		}),
195→
196→	// PROTECTED - List responses for a survey
197→	list: organizationProcedure
198→		.input(responseListSchema)
199→		.handler(async ({ input, context }) => {
200→			await verifySurveyAccess(input.surveyId, context.activeOrganization.id);
201→
202→			const { page, limit, surveyId, isComplete } = input;
203→			const offset = (page - 1) * limit;
204→
205→			const conditions = [eq(response.surveyId, surveyId)];
206→			if (isComplete !== undefined) {
207→				conditions.push(eq(response.isComplete, isComplete));
208→			}
209→
210→			const [responses, totalResult] = await Promise.all([
211→				db
212→					.select()
213→					.from(response)
214→					.where(and(...conditions))
215→					.orderBy(desc(response.createdAt))
216→					.limit(limit)
217→					.offset(offset),
218→				db
219→					.select({ count: count() })
220→					.from(response)
221→					.where(and(...conditions)),
222→			]);
223→
224→			return {
225→				data: responses,
226→				pagination: {
227→					page,
228→					limit,
229→					total: totalResult[0]?.count ?? 0,
230→					totalPages: Math.ceil((totalResult[0]?.count ?? 0) / limit),
231→				},
232→			};
233→		}),
234→
235→	// PROTECTED - Get single response with answers
236→	getById: organizationProcedure
237→		.input(z.object({ id: z.string() }))
238→		.handler(async ({ input, context }) => {
239→			const result = await db
240→				.select()
241→				.from(response)
242→				.where(eq(response.id, input.id))
243→				.limit(1);
244→
245→			if (!result[0]) {
246→				throw new Error("Response not found");
247→			}
248→
249→			// Verify survey access
250→			await verifySurveyAccess(
251→				result[0].surveyId,
252→				context.activeOrganization.id,
253→			);
254→
255→			// Get answers - we'd need an answer table query here
256→			// For now, return the response without answers
257→			return result[0];
258→		}),
259→
260→	// PROTECTED - Get response stats for a survey
261→	getStats: organizationProcedure
262→		.input(z.object({ surveyId: z.string() }))
263→		.handler(async ({ input, context }) => {
264→			await verifySurveyAccess(input.surveyId, context.activeOrganization.id);
265→
266→			const [totalResult, completeResult, partialResult] = await Promise.all([
267→				db
268→					.select({ count: count() })
269→					.from(response)
270→					.where(eq(response.surveyId, input.surveyId)),
271→				db
272→					.select({ count: count() })
273→					.from(response)
274→					.where(
275→						and(
276→							eq(response.surveyId, input.surveyId),
277→							eq(response.isComplete, true),
278→						),
279→					),
280→				db
281→					.select({ count: count() })
282→					.from(response)
283→					.where(
284→						and(
285→							eq(response.surveyId, input.surveyId),
286→							eq(response.isComplete, false),
287→						),
288→					),
289→			]);
290→
291→			return {
292→				total: totalResult[0]?.count ?? 0,
293→				complete: completeResult[0]?.count ?? 0,
294→				partial: partialResult[0]?.count ?? 0,
295→			};
296→		}),
297→
298→	// PROTECTED - Delete single response
299→	delete: adminProcedure
300→		.input(z.object({ id: z.string() }))
301→		.handler(async ({ input, context }) => {
302→			const result = await db
303→				.select()
304→				.from(response)
305→				.where(eq(response.id, input.id))
306→				.limit(1);
307→
308→			if (!result[0]) {
309→				throw new Error("Response not found");
310→			}
311→
312→			await verifySurveyAccess(
313→				result[0].surveyId,
314→				context.activeOrganization.id,
315→			);
316→
317→			await db.delete(response).where(eq(response.id, input.id));
318→			return { success: true };
319→		}),
320→
321→	// PROTECTED - Bulk delete responses
322→	bulkDelete: adminProcedure
323→		.input(z.object({ ids: z.array(z.string()) }))
324→		.handler(async ({ input, context }) => {
325→			if (input.ids.length === 0) {
326→				return { success: true, deletedCount: 0 };
327→			}
328→
329→			const responses = await db
330→				.select()
331→				.from(response)
332→				.where(inArray(response.id, input.ids));
333→
334→			if (responses.length !== input.ids.length) {
335→				throw new Error("Some responses not found");
336→			}
337→
338→			// Verify survey access for first response
339→			const firstResponse = responses[0];
340→			if (!firstResponse) {
341→				throw new Error("No responses found");
342→			}
343→			await verifySurveyAccess(
344→				firstResponse.surveyId,
345→				context.activeOrganization.id,
346→			);
347→
348→			await db.delete(response).where(inArray(response.id, input.ids));
349→
350→			return { success: true, deletedCount: responses.length };
351→		}),
352→};
