interface DistributionPanelProps {
	orgSlug: string;
	surveySlug: string;
	status?: string;
	baseUrl?: string;
	className?: string;
}

export function DistributionPanel({
	orgSlug,
	surveySlug,
	status = "draft",
	baseUrl = typeof window !== "undefined" ? window.location.origin : "",
	className,
}: DistributionPanelProps) {
