     3→import { CheckCircle2, ExternalLink } from "lucide-react";
     4→import { useRouter } from "next/navigation";
     5→import { useEffect, useState } from "react";
     6→import { Button } from "@/components/ui/button";
     7→
     8→interface SurveyOrganization {
     9→	id: string;
    10→	name: string;
    11→	slug: string;
    12→	logo: string | null;
    13→}
    14→
    15→interface SurveyWithOrg {
    16→	slug: string;
    17→	settings?: { thankYouMessage?: string; redirectUrl?: string } | null;
    18→	organization?: SurveyOrganization;
    19→}
    20→
    21→import {
    22→	Card,
    23→	CardContent,
    24→	CardFooter,
    25→	CardHeader,
    26→	CardTitle,
    27→} from "@/components/ui/card";
    28→
    29→import { useSurveyRunner } from "./context";
    30→
    31→interface RunnerCompleteProps {
    32→	message?: string;
    33→	redirectUrl?: string;
    34→}
    35→
    36→export function RunnerComplete({ message, redirectUrl }: RunnerCompleteProps) {
    37→	const { survey } = useSurveyRunner();
    38→	const router = useRouter();
    39→	const [countdown, setCountdown] = useState(5);
    40→
    41→	const orgSlug = (survey as SurveyWithOrg).organization?.slug;
    42→	const surveySlug = survey.slug;
    43→
    44→	// Use props if provided, otherwise fall back to survey settings
    45→	const thankYouMessage =
    46→		message ??
    47→		survey.settings?.thankYouMessage ??
    48→		"Thank you for completing this survey!";
    49→	const finalRedirectUrl = redirectUrl ?? survey.settings?.redirectUrl;
    50→
    51→	// Auto-redirect countdown
    52→	useEffect(() => {
    53→		if (!finalRedirectUrl) return;
    54→
    55→		const timer = setInterval(() => {
    56→			setCountdown((prev) => {
    57→				if (prev <= 1) {
    58→					clearInterval(timer);
    59→					window.location.href = finalRedirectUrl;
    60→					return 0;
    61→				}
    62→				return prev - 1;
    63→			});
    64→		}, 1000);
    65→
    66→		return () => clearInterval(timer);
    67→	}, [finalRedirectUrl]);
    68→
    69→	const handleRedirectNow = () => {
    70→		if (finalRedirectUrl) {
    71→			window.location.href = finalRedirectUrl;
    72→		}
    73→	};
    74→
    75→	return (
    76→		<div className="flex min-h-[50vh] items-center justify-center px-4 py-6">
    77→			<div className="mx-auto w-full max-w-lg">
    78→				<Card>
    79→					<CardHeader className="text-center">
    80→						<div className="mx-auto mb-4 flex size-16 items-center justify-center rounded-full bg-success/10">
    81→							<CheckCircle2 className="size-8 text-success" />
    82→						</div>
    83→						<CardTitle className="text-2xl">Survey Complete</CardTitle>
    84→					</CardHeader>
    85→
    86→					<CardContent className="text-center">
    87→						<p className="text-muted-foreground">{thankYouMessage}</p>
    88→
    89→						{finalRedirectUrl && countdown > 0 && (
    90→							<p className="mt-4 text-muted-foreground text-sm">
    91→								Redirecting in {countdown} seconds...
    92→							</p>
    93→						)}
    94→					</CardContent>
    95→
    96→					<CardFooter className="flex flex-col gap-2">
    97→						{finalRedirectUrl && (
    98→							<Button
    99→								variant="default"
   100→								className="w-full"
   101→								onClick={handleRedirectNow}
   102→							>
   103→								Continue
   104→								<ExternalLink className="ml-2 size-4" />
   105→							</Button>
   106→						)}
   107→
   108→						<Button
   109→							variant="outline"
   110→							className="w-full"
   111→							onClick={() =>
   112→								orgSlug && router.push(`/s/${orgSlug}/${surveySlug}`)
   113→							}
   114→							disabled={!orgSlug}
   115→						>
   116→							Back to Survey
   117→						</Button>
   118→					</CardFooter>
   119→				</Card>
   120→			</div>
   121→		</div>
   122→	);
   123→}
   124→

