     1→"use client";
     2→
     3→import type {
     4→	LogicRule,
     5→	Question,
     6→	Survey,
     7→	SurveySettings,
     8→} from "@orksys-survey/db";
     9→import { createContext, useContext } from "react";
    10→
    11→interface SurveyOrganization {
    12→	id: string;
    13→	name: string;
    14→	slug: string;
    15→	logo: string | null;
    16→}
    17→
    18→interface SurveyWithOrg extends Omit<Survey, "organization"> {
    19→	organization: SurveyOrganization;
    20→}
    21→
    22→import { useRunnerActions } from "./hooks/use-runner-actions";
    23→import { useRunnerState } from "./hooks/use-runner-state";
    24→
    25→export type AnswerValue = unknown;
    26→
    27→interface SurveyRunnerContextValue {
    28→	// Survey data
    29→	survey: Survey | SurveyWithOrg;
    30→	questions: Question[];
    31→	settings: SurveySettings | null;
    32→	logicRules: LogicRule[];
    33→	displayMode: "one_at_a_time" | "list";
    34→
    35→	// Response state
    36→	answers: Map<string, AnswerValue>;
    37→	currentQuestionIndex: number;
    38→	visibleQuestionIds: Set<string>;
    39→	visibleQuestions: Question[];
    40→
    41→	// Navigation
    42→	canGoBack: boolean;
    43→	canGoNext: boolean;
    44→	isComplete: boolean;
    45→	isSubmitting: boolean;
    46→
    47→	// Actions
    48→	setAnswer: (questionId: string, value: AnswerValue) => void;
    49→	goNext: () => void;
    50→	goBack: () => void;
    51→	submit: () => Promise<void>;
    52→	validateAllQuestions: () => Map<string, string>;
    53→
    54→	// Metadata
    55→	fingerprint: string | null;
    56→
    57→	// Error state
    58→	currentError: string | null;
    59→	clearError: () => void;
    60→}
    61→
    62→const SurveyRunnerContext = createContext<SurveyRunnerContextValue | null>(
    63→	null,
    64→);
    65→
    66→export function useSurveyRunner() {
    67→	const context = useContext(SurveyRunnerContext);
    68→	if (!context) {
    69→		throw new Error(
    70→			"useSurveyRunner must be used within a SurveyRunner component",
    71→		);
    72→	}
    73→	return context;
    74→}
    75→
    76→interface SurveyRunnerProviderProps {
    77→	survey: Survey | SurveyWithOrg;
    78→	questions: Question[];
    79→	logicRules?: LogicRule[];
    80→	children: React.ReactNode;
    81→	onComplete?: () => void;
    82→}
    83→
    84→export function SurveyRunnerProvider({
    85→	survey,
    86→	questions,
    87→	logicRules = [],
    88→	children,
    89→	onComplete,
    90→}: SurveyRunnerProviderProps) {
    91→	// State management
    92→	const state = useRunnerState({
    93→		survey,
    94→		questions,
    95→		logicRules,
    96→	});
    97→
    98→	// Actions
    99→	const actions = useRunnerActions({
   100→		survey,
   101→		visibleQuestions: state.visibleQuestions,
   102→		sortedQuestions: state.sortedQuestions,
   103→		currentQuestionIndex: state.currentQuestionIndex,
   104→		answers: state.answers,
   105→		fingerprint: state.fingerprint,
   106→		setAnswers: state.setAnswers,
   107→		setCurrentQuestionIndex: state.setCurrentQuestionIndex,
   108→		setIsComplete: state.setIsComplete,
   109→		onComplete,
   110→	});
   111→
   112→	const value: SurveyRunnerContextValue = {
   113→		survey: state.survey,
   114→		questions: state.questions,
   115→		settings: state.settings,
   116→		logicRules: state.logicRules as LogicRule[],
   117→		displayMode: state.displayMode,
   118→		answers: state.answers,
   119→		currentQuestionIndex: state.currentQuestionIndex,
   120→		visibleQuestionIds: state.visibleQuestionIds,
   121→		visibleQuestions: state.visibleQuestions,
   122→		canGoBack: state.canGoBack,
   123→		canGoNext: state.canGoNext,
   124→		isComplete: state.isComplete,
   125→		isSubmitting: actions.isSubmitting,
   126→		setAnswer: actions.setAnswer,
   127→		goNext: actions.goNext,
   128→		goBack: actions.goBack,
   129→		submit: actions.submit,
   130→		validateAllQuestions: actions.validateAllQuestions,
   131→		fingerprint: state.fingerprint,
   132→		currentError: actions.currentError,
   133→		clearError: actions.clearError,
   134→	};
   135→
   136→	return (
   137→		<SurveyRunnerContext.Provider value={value}>
   138→			{children}
   139→		</SurveyRunnerContext.Provider>
   140→	);
   141→}
