    28→}
    29→
    30→export interface QuestionDragItem {
    31→	type: "question";
    32→	id: string;
    33→}
    34→
    35→export type DragItem = PaletteDragItem | QuestionDragItem;
    36→
    37→interface BuilderCanvasProps {
    38→	questions: Question[];
    39→	onQuestionsChange: (questions: Question[]) => void;
    40→	activeDragItem: DragItem | null;
    41→	overId: string | null;
