    43→
    44→export function BuilderCanvas({
    45→	questions,
    46→	onQuestionsChange,
    47→	activeDragItem,
    48→	overId,
    49→}: BuilderCanvasProps) {
    50→	const { survey, selectedQuestionId, setSelectedQuestionId, activeTab } =
    51→		useSurveyBuilder();
    52→
    53→	const queryClient = useQueryClient();
    54→
    55→	// Make canvas droppable
    56→	const { setNodeRef, isOver } = useDroppable({
    57→		id: "canvas",
    58→	});
    59→
    60→	const safeQuestions = questions || [];
    61→
    62→	const createMutation = useMutation(
    63→		orpc.question.create.mutationOptions({
    64→			onSuccess: (newQuestion) => {
    65→				onQuestionsChange([...questions, newQuestion]);
    66→				setSelectedQuestionId(newQuestion.id);
    67→				queryClient.invalidateQueries({ queryKey: ["question"] });
    68→				toast.success("Question added");
    69→			},
    70→			onError: (error) => {
    71→				toast.error(error.message || "Failed to create question");
    72→			},
    73→		}),
    74→	);
    75→
    76→	const handleAddQuestion = () => {
    77→		createMutation.mutate({
    78→			surveyId: survey.id,
    79→			type: "text",
    80→			title: "New Question",
    81→			order: safeQuestions.length,
    82→		});
    83→	};
    84→
    85→	// Render different tabs
    86→	if (activeTab === "share") {
    87→		const orgSlug = survey.organization?.slug;
    88→		if (!orgSlug) {
    89→			return (
    90→				<div className="flex h-full items-center justify-center">
    91→					<div className="text-center">
    92→						<p className="text-muted-foreground">
    93→							Organization information not available
    94→						</p>
    95→					</div>
    96→				</div>
    97→			);
    98→		}
    99→		return (
   100→			<ShareCanvas
   101→				orgSlug={orgSlug}
   102→				surveySlug={survey.slug}
   103→				status={survey.status}
   104→			/>
   105→		);
   106→	}
   107→
   108→	if (activeTab === "preview") {
   109→		return <PreviewCanvas questions={safeQuestions} />;
   110→	}
   111→
   112→	// Calculate drop position based on overId
   113→	const rawDropIndex = overId
   114→		? safeQuestions.findIndex((q) => q.id === overId)
   115→		: -1;
   116→	const dropIndex = rawDropIndex === -1 ? safeQuestions.length : rawDropIndex;
   117→
   118→	// Get the question type being dragged
   119→	const isDraggingPalette = activeDragItem?.type === "palette";
   120→	const draggedQuestionType = isDraggingPalette
   121→		? activeDragItem.questionType
   122→		: undefined;
   123→
   124→	return (
   125→		<div
   126→			ref={setNodeRef}
   127→			className={`flex flex-1 flex-col overflow-y-auto bg-muted/30 p-6 transition-colors ${
   128→				isOver ? "bg-primary/5" : ""
   129→			}`}
   130→		>
   131→			<div className="mx-auto w-full max-w-2xl space-y-3">
   132→				<AnimatePresence mode="popLayout" initial={false}>
   133→					{safeQuestions.length === 0 ? (
   134→						<EmptyCanvas
   135→							isOver={isOver}
   136→							onAddQuestion={handleAddQuestion}
   137→							isPending={createMutation.isPending}
   138→						/>
   139→					) : (
   140→						<>
   141→							<SortableContext
   142→								items={safeQuestions.map((q) => q.id)}
   143→								strategy={verticalListSortingStrategy}
   144→							>
   145→								{safeQuestions.map((question, index) => (
   146→									<React.Fragment key={question.id}>
   147→										{/* Add drop indicator before this question if dragging over it */}
   148→										{isDraggingPalette &&
   149→											index === dropIndex &&
   150→											draggedQuestionType && (
   151→												<DropIndicator
   152→													questionType={draggedQuestionType}
   153→													position="middle"
   154→												/>
   155→											)}
   156→
   157→										{/* Add the question card */}
   158→										<motion.div
   159→											layout={!activeDragItem ? "position" : false}
   160→											initial={
   161→												question.id.startsWith("temp-")
   162→													? { opacity: 0, y: 20, scale: 0.95 }
   163→													: false
   164→											}
   165→											animate={{ opacity: 1, y: 0, scale: 1 }}
   166→											exit={{
   167→												opacity: 0,
   168→												scale: 0.95,
   169→												transition: { duration: 0.15 },
   170→											}}
   171→											transition={{
   172→												type: "spring",
   173→												stiffness: 400,
   174→												damping: 30,
   175→												mass: 0.8,
   176→											}}
   177→										>
   178→											<QuestionCard
   179→												question={question}
   180→												isSelected={selectedQuestionId === question.id}
   181→												onSelect={() => setSelectedQuestionId(question.id)}
   182→												questions={safeQuestions}
   183→												onQuestionsChange={onQuestionsChange}
   184→											/>
   185→										</motion.div>
   186→									</React.Fragment>
   187→								))}
   188→
   189→								{/* Add indicator at end if hovering at last position or over canvas */}
   190→								{isDraggingPalette &&
   191→									dropIndex >= safeQuestions.length &&
   192→									draggedQuestionType && (
   193→										<DropIndicator
   194→											questionType={draggedQuestionType}
   195→											position="end"
   196→										/>
   197→									)}
   198→							</SortableContext>
   199→
   200→							<motion.div
   201→								initial={{ opacity: 0 }}
   202→								animate={{ opacity: 1 }}
   203→								transition={{ delay: 0.1 }}
   204→							>
   205→								<Button
   206→									variant="outline"
   207→									className="w-full border-dashed"
   208→									onClick={handleAddQuestion}
   209→									disabled={createMutation.isPending}
   210→								>
   211→									<Plus className="mr-2 h-4 w-4" />
   212→									Add Question
   213→								</Button>
   214→							</motion.div>
   215→						</>
   216→					)}
   217→				</AnimatePresence>
   218→			</div>
   219→		</div>
   220→	);
   221→}
   222→
