    37→
    38→export function SurveyBuilder({
    39→	survey,
    40→	questions: initialQuestions,
    41→	className,
    42→}: SurveyBuilderProps) {
    43→	const [selectedQuestionId, setSelectedQuestionId] = useState<string | null>(
    44→		null,
    45→	);
    46→	const [activeTab, setActiveTab] = useState<"build" | "preview" | "share">(
    47→		"build",
    48→	);
    49→	const [questions, setQuestions] = useState(initialQuestions);
