    53→
    54→	// Responsive breakpoints
    55→	const isDesktop = useMediaQuery("(min-width: 1024px)");
    56→
    57→	// Sync state when initialQuestions changes
    58→	useEffect(() => {
    59→		setQuestions(initialQuestions);
    60→	}, [initialQuestions]);
    61→
    62→	// Get mutations
    63→	const { reorderMutation } = useQuestionMutations({
    64→		survey,
    65→		onQuestionCreated: (newQuestion) => {
    66→			// Replace optimistic question with real one
    67→			setQuestions((currentQuestions) => {
    68→				const tempId = selectedQuestionId?.startsWith("temp-")
    69→					? selectedQuestionId
    70→					: null;
    71→				if (!tempId) return currentQuestions;
    72→
    73→				return currentQuestions.map((q) => (q.id === tempId ? newQuestion : q));
    74→			});
    75→
    76→			setSelectedQuestionId((currentId) => {
    77→				const tempId = currentId?.startsWith("temp-") ? currentId : null;
    78→				return tempId ? newQuestion.id : currentId;
    79→			});
    80→		},
    81→		onQuestionCreateError: () => {
    82→			// Revert on error
    83→			if (selectedQuestionId?.startsWith("temp-")) {
    84→				setSelectedQuestionId(null);
    85→			}
    86→		},
    87→	});
