    90→	const {
    91→		activeDragItem,
    92→		overId,
    93→		collisionDetection,
    94→		handleDragStart,
    95→		handleDragOver,
    96→		handleDragEnd,
    97→	} = useDragHandlers({
    98→		questions,
    99→		setQuestions,
   100→		survey,
   101→		selectedQuestionId,
   102→		setSelectedQuestionId,
   103→		reorderMutation,
   104→	});
   105→
   106→	// DnD sensors
   107→	const sensors = useSensors(
   108→		useSensor(PointerSensor, {
   109→			activationConstraint: {
   110→				distance: 5,
   111→			},
   112→		}),
   113→		useSensor(KeyboardSensor, {
   114→			coordinateGetter: sortableKeyboardCoordinates,
   115→		}),
   116→	);
   117→
   118→	const safeQuestions = questions || [];
   119→
   120→	return (
   121→		<SurveyBuilderProvider
   122→			survey={survey}
   123→			questions={questions}
   124→			selectedQuestionId={selectedQuestionId}
   125→			setSelectedQuestionId={setSelectedQuestionId}
   126→			activeTab={activeTab}
   127→			setActiveTab={setActiveTab}
   128→			onQuestionsChange={setQuestions}
   129→			paletteOpen={paletteOpen}
   130→			setPaletteOpen={setPaletteOpen}
   131→			propertiesOpen={propertiesOpen}
   132→			setPropertiesOpen={setPropertiesOpen}
   133→			settingsOpen={settingsOpen}
   134→			setSettingsOpen={setSettingsOpen}
   135→		>
