    61→// Verify survey belongs to organization
    62→async function verifySurveyAccess(
    63→	surveyId: string,
    64→	organizationId: string,
    65→): Promise<void> {
    66→	const result = await db
    67→		.select()
    68→		.from(survey)
    69→		.where(
    70→			and(eq(survey.id, surveyId), eq(survey.organizationId, organizationId)),
    71→		)
    72→		.limit(1);
    73→
    74→	if (!result[0]) {
    75→		throw new Error("Survey not found");
    76→	}
    77→}
