    79→export const responseRouter = {
    80→	// PUBLIC - Get published survey for runner
    81→	getSurveyForRunner: publicProcedure
    82→		.input(z.object({ orgSlug: z.string(), surveySlug: z.string() }))
    83→		.handler(async ({ input }) => {
    84→			const surveyResult = await db
    85→				.select({
    86→					survey: survey,
    87→					organization: {
    88→						id: organization.id,
    89→						name: organization.name,
    90→						slug: organization.slug,
    91→						logo: organization.logo,
    92→					},
    93→				})
    94→				.from(survey)
    95→				.innerJoin(organization, eq(survey.organizationId, organization.id))
    96→				.where(
    97→					and(
    98→						eq(survey.slug, input.surveySlug),
    99→						eq(organization.slug, input.orgSlug),
   100→						eq(survey.status, "published"),
   101→					),
   102→				)
   103→				.limit(1);
   104→
   105→			if (!surveyResult[0]) {
   106→				throw new Error("Survey not found or not published");
   107→			}
   108→
   109→			const surveyData = surveyResult[0].survey;
   110→
   111→			// Get questions and logic rules for the survey in parallel
   112→			const [questions, logicRules] = await Promise.all([
   113→				db
   114→					.select()
   115→					.from(question)
   116→					.where(eq(question.surveyId, surveyData.id))
   117→					.orderBy(question.order),
   118→				db
   119→					.select()
   120→					.from(logicRule)
   121→					.where(eq(logicRule.surveyId, surveyData.id)),
   122→			]);
   123→
   124→			return {
   125→				survey: {
   126→					...surveyData,
   127→					organization: surveyResult[0].organization,
   128→				},
   129→				questions,
   130→				logicRules,
   131→			};
   132→		}),
   133→
   134→	// PUBLIC - Submit response
   135→	submit: publicProcedure
   136→		.input(submitResponseSchema)
   137→		.handler(async ({ input }) => {
   138→			// Verify survey exists and is published
   139→			const surveyResult = await db
   140→				.select()
   141→				.from(survey)
   142→				.where(
   143→					and(eq(survey.id, input.surveyId), eq(survey.status, "published")),
   144→				)
   145→				.limit(1);
   146→
   147→			if (!surveyResult[0]) {
   148→				throw new Error("Survey not found or not published");
   149→			}
   150→
   151→			// Check for duplicate fingerprint if provided and multiple responses NOT allowed
   152→			if (
   153→				input.fingerprint &&
   154→				!surveyResult[0].settings?.allowMultipleResponses
   155→			) {
   156→				const existingResponse = await db
   157→					.select()
   158→					.from(response)
   159→					.where(
   160→						and(
   161→							eq(response.surveyId, input.surveyId),
   162→							eq(response.fingerprint, input.fingerprint),
   163→						),
   164→					)
   165→					.limit(1);
   166→
   167→				if (existingResponse[0]) {
   168→					throw new Error("You have already responded to this survey");
   169→				}
   170→			}
   171→
   172→			// Verify all questions belong to this survey
   173→			const questionIds = input.answers.map((a) => a.questionId);
   174→			if (questionIds.length > 0) {
   175→				const questions = await db
   176→					.select()
   177→					.from(question)
   178→					.where(inArray(question.id, questionIds));
   179→
   180→				for (const q of questions) {
   181→					if (q.surveyId !== input.surveyId) {
   182→						throw new Error(`Question ${q.id} does not belong to this survey`);
   183→					}
   184→				}
   185→			}
   186→
   187→			// Create response and answers in a transaction
   188→			const responseId = generateResponseId();
   189→			const now = new Date();
   190→
   191→			await db.insert(response).values({
   192→				id: responseId,
   193→				surveyId: input.surveyId,
   194→				respondentId: input.respondentId ?? null,
   195→				fingerprint: input.fingerprint ?? null,
   196→				metadata: input.metadata ?? null,
   197→				isComplete: input.isComplete,
   198→				startedAt: now,
   199→				completedAt: input.isComplete ? now : null,
   200→			});
   201→
   202→			// Insert answers
   203→			if (input.answers.length > 0) {
   204→				const answersToInsert = input.answers.map((a) => ({
   205→					id: generateAnswerId(),
   206→					responseId,
   207→					questionId: a.questionId,
   208→					value: a.value,
   209→				}));
   210→
   211→				await db.insert(answer).values(answersToInsert);
   212→			}
   213→
   214→			return { success: true, responseId };
   215→		}),
