   217→	// PROTECTED - List responses for a survey
   218→	list: organizationProcedure
   219→		.input(responseListSchema)
   220→		.handler(async ({ input, context }) => {
   221→			await verifySurveyAccess(input.surveyId, context.activeOrganization.id);
   222→
   223→			const { page, limit, surveyId, isComplete } = input;
   224→			const offset = (page - 1) * limit;
   225→
   226→			const conditions = [eq(response.surveyId, surveyId)];
   227→			if (isComplete !== undefined) {
   228→				conditions.push(eq(response.isComplete, isComplete));
   229→			}
   230→
   231→			const [responses, totalResult] = await Promise.all([
   232→				db
   233→					.select()
   234→					.from(response)
   235→					.where(and(...conditions))
   236→					.orderBy(desc(response.createdAt))
   237→					.limit(limit)
   238→					.offset(offset),
   239→				db
   240→					.select({ count: count() })
   241→					.from(response)
   242→					.where(and(...conditions)),
   243→			]);
   244→
   245→			return {
   246→				data: responses,
   247→				pagination: {
   248→					page,
   249→					limit,
   250→					total: totalResult[0]?.count ?? 0,
   251→					totalPages: Math.ceil((totalResult[0]?.count ?? 0) / limit),
   252→				},
   253→			};
   254→		}),
   255→
   256→	// PROTECTED - Get single response with answers
   257→	getById: organizationProcedure
   258→		.input(z.object({ id: z.string() }))
   259→		.handler(async ({ input, context }) => {
   260→			const result = await db
   261→				.select()
   262→				.from(response)
   263→				.where(eq(response.id, input.id))
   264→				.limit(1);
   265→
   266→			if (!result[0]) {
   267→				throw new Error("Response not found");
   268→			}
   269→
   270→			// Verify survey access
   271→			await verifySurveyAccess(
   272→				result[0].surveyId,
   273→				context.activeOrganization.id,
   274→			);
   275→
   276→			// Get answers - we'd need an answer table query here
   277→			// For now, return the response without answers
   278→			return result[0];
   279→		}),
   280→
   281→	// PROTECTED - Get response stats for a survey
   282→	getStats: organizationProcedure
   283→		.input(z.object({ surveyId: z.string() }))
   284→		.handler(async ({ input, context }) => {
   285→			await verifySurveyAccess(input.surveyId, context.activeOrganization.id);
   286→
   287→			const [totalResult, completeResult, partialResult] = await Promise.all([
   288→				db
   289→					.select({ count: count() })
   290→					.from(response)
   291→					.where(eq(response.surveyId, input.surveyId)),
   292→				db
   293→					.select({ count: count() })
   294→					.from(response)
   295→					.where(
   296→						and(
   297→							eq(response.surveyId, input.surveyId),
   298→							eq(response.isComplete, true),
   299→						),
   300→					),
   301→				db
   302→					.select({ count: count() })
   303→					.from(response)
   304→					.where(
   305→						and(
   306→							eq(response.surveyId, input.surveyId),
   307→							eq(response.isComplete, false),
   308→						),
   309→					),
   310→			]);
   311→
   312→			return {
   313→				total: totalResult[0]?.count ?? 0,
   314→				complete: completeResult[0]?.count ?? 0,
   315→				partial: partialResult[0]?.count ?? 0,
   316→			};
   317→		}),
   318→
   319→	// PROTECTED - Delete single response
   320→	delete: adminProcedure
   321→		.input(z.object({ id: z.string() }))
   322→		.handler(async ({ input, context }) => {
   323→			const result = await db
   324→				.select()
   325→				.from(response)
   326→				.where(eq(response.id, input.id))
   327→				.limit(1);
   328→
   329→			if (!result[0]) {
   330→				throw new Error("Response not found");
   331→			}
   332→
   333→			await verifySurveyAccess(
   334→				result[0].surveyId,
   335→				context.activeOrganization.id,
   336→			);
   337→
   338→			await db.delete(response).where(eq(response.id, input.id));
   339→			return { success: true };
   340→		}),
   341→
   342→	// PROTECTED - Bulk delete responses
   343→	bulkDelete: adminProcedure
   344→		.input(z.object({ ids: z.array(z.string()) }))
   345→		.handler(async ({ input, context }) => {
   346→			if (input.ids.length === 0) {
   347→				return { success: true, deletedCount: 0 };
   348→			}
   349→
   350→			const responses = await db
   351→				.select()
   352→				.from(response)
   353→				.where(inArray(response.id, input.ids));
   354→
   355→			if (responses.length !== input.ids.length) {
   356→				throw new Error("Some responses not found");
   357→			}
   358→
   359→			// Verify survey access for first response
   360→			const firstResponse = responses[0];
   361→			if (!firstResponse) {
   362→				throw new Error("No responses found");
   363→			}
   364→			await verifySurveyAccess(
   365→				firstResponse.surveyId,
   366→				context.activeOrganization.id,
   367→			);
   368→
   369→			await db.delete(response).where(inArray(response.id, input.ids));
   370→
   371→			return { success: true, deletedCount: responses.length };
   372→		}),
   373→};
